package com.icewright.generated.service;

import com.icewright.generated.config.Settings;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * 身份与隔离：组 / 会话 / 用户 / 用户类型四层隔离的框架层实现（与 python/go 栈同形契约）。
 *
 * <p>默认实现=客户网关注入 X-IW-User / X-IW-Group / X-IW-Role 头 + HMAC-SHA256 共享密钥验签
 * （IW_AUTH_SECRET）；客户已有统一认证体系（OAuth/SSO/自有签名）时只替换 identify 一个方法，
 * 业务代码不动。权限闸门收口在 HTTP 层，不依赖模型自觉（设计文档第 9 节）。</p>
 *
 * @author IceWright builder
 */
@Service
public class IdentityService {

    /** 身份四元组；signed=是否经共享密钥验签。 */
    public record Identity(String user, String group, String role, boolean signed) {
    }

    private static final List<String> ROLES = List.of("developer", "agent", "customer");
    private static final Pattern ID_PATTERN = Pattern.compile("^[A-Za-z0-9_.:-]{1,128}$");
    private static final String OWNER_PREFIX = "sess:";

    private final SessionService sessionService;

    public IdentityService(SessionService sessionService) {
        this.sessionService = sessionService;
    }

    /** 共享密钥：默认取 IW_AUTH_SECRET；接入自有认证时覆写本方法即整层替换点。 */
    protected String authSecret() {
        return Settings.AUTH_SECRET;
    }

    public boolean devMode() {
        return authSecret().isEmpty();
    }

    /**
     * 解析并校验身份请求头：验签失败 401，角色非法 403，标识字符集非法 400。
     *
     * <p>调试模式（未配 IW_AUTH_SECRET）下不带任何头=本机开发者，直连后台页面可用；
     * 一旦配置密钥，所有请求都必须带签名头——生产环境无免签通道。</p>
     */
    public Identity identify(HttpServletRequest request) {
        String user = header(request, "X-IW-User");
        String group = header(request, "X-IW-Group");
        String role = header(request, "X-IW-Role");
        if (user.isEmpty() && group.isEmpty() && role.isEmpty()) {
            if (!devMode()) {
                throw new ResponseStatusException(
                    HttpStatus.UNAUTHORIZED, "缺少身份请求头（X-IW-User/X-IW-Group/X-IW-Role）");
            }
            return new Identity("dev-local", "default", "developer", false);
        }
        if (!ID_PATTERN.matcher(user).matches() || !ID_PATTERN.matcher(group).matches()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "user/group 标识字符集非法");
        }
        if (!ROLES.contains(role)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "用户类型不在允许集合: " + role);
        }
        if (!devMode() && !MessageDigest.isEqual(
            sign(user, group, role).getBytes(StandardCharsets.UTF_8),
            header(request, "X-IW-Sign").getBytes(StandardCharsets.UTF_8))) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "签名校验失败（X-IW-Sign 与共享密钥不符）");
        }
        return new Identity(user, group, role, !devMode());
    }

    /** X-IW-Sign 计算口径：HMAC-SHA256(secret, "user|group|role") 十六进制小写（三栈一致）。 */
    public String sign(String user, String group, String role) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(authSecret().getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            byte[] raw = mac.doFinal((user + "|" + group + "|" + role).getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(raw.length * 2);
            for (byte b : raw) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16)).append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("HMAC 计算失败", e);
        }
    }

    /** 会话首用绑定 用户+组；此后仅所有者或 developer 可用（活跃即续期）。 */
    public void ensureSession(Identity identity, String sessionId) {
        Map<String, Object> owner = sessionService.getRecord(OWNER_PREFIX + sessionId);
        if (owner == null) {
            Map<String, Object> binding = new LinkedHashMap<>();
            binding.put("user", identity.user());
            binding.put("group", identity.group());
            sessionService.putRecord(OWNER_PREFIX + sessionId, binding);
            return;
        }
        assertOwned(identity, owner);
        sessionService.putRecord(OWNER_PREFIX + sessionId, owner);
    }

    /** 只读校验（不登记归属）：developer 全量可见，其余须与登记所有者同用户同组。 */
    public void viewable(Identity identity, String sessionId) {
        Map<String, Object> owner = sessionService.getRecord(OWNER_PREFIX + sessionId);
        if (owner != null) {
            assertOwned(identity, owner);
        }
    }

    public void requireRole(Identity identity, String... roles) {
        for (String role : roles) {
            if (role.equals(identity.role())) {
                return;
            }
        }
        throw new ResponseStatusException(HttpStatus.FORBIDDEN,
            "该端点仅限 " + String.join("/", roles) + "，当前用户类型: " + identity.role());
    }

    private static void assertOwned(Identity identity, Map<String, Object> owner) {
        boolean owned = identity.user().equals(owner.get("user"))
            && identity.group().equals(owner.get("group"));
        if (!"developer".equals(identity.role()) && !owned) {
            throw new ResponseStatusException(
                HttpStatus.FORBIDDEN, "会话归属其他用户或组（会话/用户/组隔离生效）");
        }
    }

    private static String header(HttpServletRequest request, String name) {
        String value = request.getHeader(name);
        return value == null ? "" : value;
    }
}
